'use client';

import Link from 'next/link';
import type { Scenario } from '@/lib/types';

export type ScenarioSwitchError = {
  message: string;
  details: string[];
  target: Scenario;
};

type ScenarioSwitcherProps = {
  currentScenario: Scenario | null;
  isSwitching: boolean;
  pendingScenario: Scenario | null;
  error: ScenarioSwitchError | null;
  changeNote: string | null;
  saveWarning: string | null;
  legacy: boolean;
  onSelect: (scenario: Scenario) => void;
  onRetry: () => void;
};

const scenarioLabels: Record<Scenario, string> = {
  slow: 'AI 变化较缓',
  fast: 'AI 变化较快',
};

const scenarioOptions: Scenario[] = ['slow', 'fast'];

export function ScenarioSwitcher({
  currentScenario,
  isSwitching,
  pendingScenario,
  error,
  changeNote,
  saveWarning,
  legacy,
  onSelect,
  onRetry,
}: ScenarioSwitcherProps) {
  return (
    <section
      aria-label="情景切换"
      className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"
    >
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-sm font-semibold text-slate-900">情景</p>
          <p className="mt-0.5 text-xs leading-5 text-slate-500">
            切换后会重新分析岗位顺序与学习优先级，原结果会保留到新结果返回。
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <div
            role="group"
            aria-label="选择情景"
            className="inline-flex rounded-lg border border-slate-200 bg-slate-100 p-1"
          >
            {scenarioOptions.map((option) => {
              const selected = currentScenario === option;

              return (
                <button
                  key={option}
                  type="button"
                  onClick={() => onSelect(option)}
                  disabled={isSwitching || legacy}
                  aria-pressed={selected}
                  aria-label={scenarioLabels[option]}
                  title={scenarioLabels[option]}
                  className={`min-w-16 rounded-md px-4 py-1.5 text-sm font-medium transition ${
                    selected
                      ? 'bg-white text-slate-900 shadow-sm'
                      : 'text-slate-500 hover:text-slate-800'
                  } disabled:cursor-not-allowed disabled:opacity-60`}
                >
                  {option === 'slow' ? '缓' : '快'}
                </button>
              );
            })}
          </div>
          <span className="text-xs text-slate-500">
            {currentScenario ? `当前：${scenarioLabels[currentScenario]}` : '当前情景未知'}
          </span>
        </div>
      </div>

      {isSwitching && pendingScenario ? (
        <div
          role="status"
          aria-live="polite"
          className="mt-3 flex items-center gap-2 rounded-lg border border-blue-100 bg-blue-50/70 px-3 py-2.5 text-sm text-blue-700"
        >
          <span
            className="h-4 w-4 animate-spin rounded-full border-2 border-blue-200 border-t-blue-600"
            aria-hidden="true"
          />
          正在按「{scenarioLabels[pendingScenario]}」重新分析你的档案…
        </div>
      ) : null}

      {error ? (
        <div role="alert" className="mt-3 rounded-lg border border-red-200 bg-red-50 p-3">
          <p className="text-sm font-medium text-red-700">
            切换到「{scenarioLabels[error.target]}」失败
          </p>
          <p className="mt-1 text-xs leading-5 text-red-600">{error.message}</p>
          {error.details.length > 0 ? (
            <ul className="mt-1 list-disc space-y-0.5 pl-5 text-xs text-red-600">
              {error.details.map((detail) => (
                <li key={detail}>{detail}</li>
              ))}
            </ul>
          ) : null}
          <button
            type="button"
            onClick={onRetry}
            disabled={isSwitching}
            className="mt-3 rounded-md border border-red-300 bg-white px-3 py-1.5 text-xs font-medium text-red-700 transition hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-60"
          >
            重试
          </button>
        </div>
      ) : null}

      {changeNote ? (
        <p
          role="status"
          aria-live="polite"
          className="mt-3 rounded-lg border border-emerald-100 bg-emerald-50/70 px-3 py-2 text-sm leading-6 text-emerald-800"
        >
          {changeNote}
        </p>
      ) : null}

      {saveWarning ? <p className="mt-2 text-xs text-amber-600">{saveWarning}</p> : null}

      {legacy ? (
        <p className="mt-3 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-xs leading-5 text-slate-600">
          此结果来自旧版本，未保存原始档案，暂时无法切换情景。
          <Link
            href="/"
            className="ml-1 font-medium text-blue-700 underline-offset-2 hover:underline"
          >
            重新填写
          </Link>
        </p>
      ) : null}
    </section>
  );
}
